param(
    [string]$ProjectPath = (Get-Location).Path
)

$ErrorActionPreference = "Stop"

Write-Host "AfriSync assets installer"
Write-Host "Target project: $ProjectPath"

if (-not (Test-Path $ProjectPath)) {
    Write-Host "ERROR: Project path does not exist: $ProjectPath"
    exit 1
}

$assetsDir = Join-Path $ProjectPath "assets"
if (-not (Test-Path $assetsDir)) {
    New-Item -ItemType Directory -Path $assetsDir | Out-Null
    Write-Host "Created assets folder: $assetsDir"
} else {
    Write-Host "Assets folder already exists: $assetsDir"
}

$fullLogoBase64 = @'

'@

$markLogoBase64 = @'

'@

$fullLogoPath = Join-Path $assetsDir "afrisync_logo_full_1024.png"
$markLogoPath = Join-Path $assetsDir "afrisync_logo_mark_512.png"

[System.IO.File]::WriteAllBytes($fullLogoPath, [System.Convert]::FromBase64String(($fullLogoBase64 -replace "`r|`n", "")))
[System.IO.File]::WriteAllBytes($markLogoPath, [System.Convert]::FromBase64String(($markLogoBase64 -replace "`r|`n", "")))

Write-Host "Created: $fullLogoPath"
Write-Host "Created: $markLogoPath"
Write-Host "Done. AfriSync logo assets are now installed."
Write-Host "Run this to confirm: dir .\assets"
